{"action": "sql", "sql": "WITH cycle AS (
  SELECT cycle_id FROM skills.assessment_cycles WHERE name = '2025-H2'
),
assessments_2025_h2 AS (
  SELECT score FROM skills.assessments a
  JOIN cycle c ON a.cycle_id = c.cycle_id
)
SELECT ROUND(
  100.0 * COUNT(*) FILTER (WHERE score IN (4,5)) / COUNT(*),
  1
) AS percentage
FROM assessments_2025_h2;"}

{"action": "sql", "sql": "SELECT ROUND(100.0 * COUNT(DISTINCT cert.employee_id) / COUNT(DISTINCT emp.employee_id), 1) AS certification_share_pct
FROM skills.employees emp
LEFT JOIN (
  SELECT DISTINCT employee_id FROM skills.certifications
) cert ON emp.employee_id = cert.employee_id
WHERE emp.left_on IS NULL;"}
